<div class="row mb-2 align-items-end fila-dinamica" data-fila data-nov-autocompletar>
    <div class="col-md-3"><label class="campo-etiqueta" for="hab_persona_{{ $i }}">Nombre</label><input type="text" id="hab_persona_{{ $i }}" name="hab_personas[{{ $i }}][nombre]" class="campo text-uppercase" maxlength="150" list="novColaboradores" placeholder="Buscar o escribir..." value="{{ $p['nombre'] ?? '' }}" data-nov-nombre></div>
    <div class="col-md-2"><label class="campo-etiqueta" for="hab_persona_depto_{{ $i }}">Depto</label><input type="text" id="hab_persona_depto_{{ $i }}" name="hab_personas[{{ $i }}][departamento]" class="campo text-uppercase" maxlength="100" value="{{ $p['departamento'] ?? '' }}" data-nov-depto></div>
    <div class="col-md-2"><label class="campo-etiqueta" for="hab_persona_puesto_{{ $i }}">Puesto</label><input type="text" id="hab_persona_puesto_{{ $i }}" name="hab_personas[{{ $i }}][puesto]" class="campo text-uppercase" maxlength="100" value="{{ $p['puesto'] ?? '' }}" data-nov-puesto></div>
    <div class="col-md-3"><label class="campo-etiqueta" for="hab_persona_actividad_{{ $i }}">Actividad</label><input type="text" id="hab_persona_actividad_{{ $i }}" name="hab_personas[{{ $i }}][actividad]" class="campo" maxlength="255" value="{{ $p['actividad'] ?? '' }}"></div>
    <div class="col-6 col-md-1 text-md-center"><label class="campo-etiqueta d-block" for="hab_persona_retira_{{ $i }}">Se retira</label><input type="checkbox" id="hab_persona_retira_{{ $i }}" name="hab_personas[{{ $i }}][se_retira]" value="1" class="casilla-grande mb-3" @checked(! empty($p['se_retira']))></div>
